CREATE OR REPLACE FUNCTION public._perm_base(_school uuid, _uid uuid, _section text, _action text)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO public AS $function$
begin
 if _section='people_family' and _action='place' and exists(select 1 from public.schools s join public.memberships m on m.school_id=s.id and m.org_id=s.org_id where s.id=_school and s.is_active and m.user_id=_uid and m.role='vice_principal' and m.is_active and not coalesce(m.branch_suspended,false)) then return true; end if;
 if _section not in ('academic_years','academic_terms','academic_stages','academic_grades','academic_sections','academic_departments','academic_subjects','academic_scopes','course_setup','course_assignments','admin_tasks','admin_requests','admin_forms','schedule_drafts','schedule_day','schedule_rooms','schedule_requirements','schedule_loads','schedule_availability','schedule_sub_policy','duty_rosters','duty_setup') then return _perm_base_pre334(_school,_uid,_section,_action); end if;
 if _perm_owner(_uid,school_org(_school)) then return true; end if;
 return exists(select 1 from memberships m where m.school_id=_school and m.user_id=_uid and m.is_active and not coalesce(m.branch_suspended,false) and case when _section like 'academic\_%' or _section like 'schedule\_%' or _section='course_setup' then m.role='principal' when _section='course_assignments' then m.role in ('principal','dept_head') or (_action='view' and m.role in ('vice_principal','student_affairs')) when _section='admin_tasks' then case when _action in ('create','manage') then m.role in ('principal','vice_principal','supervisor') else m.role not in ('student','guardian') end when _section='admin_requests' then m.role not in ('student','guardian') when _section='admin_forms' then m.role='principal' when _section='duty_rosters' then m.role in ('principal','vice_principal') when _section='duty_setup' then m.role='principal' else false end);
end $function$;